sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 shadowColor;
layout(color) uniform half4 midColor;
layout(color) uniform half4 highColor;
uniform float midpoint;
uniform float source;
uniform float contrast;
uniform float invert;
uniform float blend;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float3 blendm(float3 b, float3 s, float m) {
    if (m < 0.5) return s;
    if (m < 1.5) return b + s;
    if (m < 2.5) return 1.0 - (1.0 - b) * (1.0 - s);
    if (m < 3.5) return b * s;
    if (m < 4.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(float3(0.5), b));
    if (m < 5.5) return (1.0 - 2.0 * s) * b * b + 2.0 * s * b;
    if (m < 6.5) return max(b, s);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return abs(b - s);
    return b / max(1.0 - s, 0.001);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float t = source < 0.5 ? luma(s) : (source < 1.5 ? s.r : (source < 2.5 ? s.g : (source < 3.5 ? s.b : max(s.r, max(s.g, s.b)))));
    t = saturate((t - 0.5) * contrast + 0.5);
    if (invert > 0.5) t = 1.0 - t;
    float mp = clamp(midpoint, 0.01, 0.99);
    float3 g = t < mp ? mix(float3(shadowColor.rgb), float3(midColor.rgb), t / mp) : mix(float3(midColor.rgb), float3(highColor.rgb), (t - mp) / (1.0 - mp));
    float3 o = blendm(s, g, blend);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
